const jobs = new Map();
let next = 1;

function enqueue(kind, params, run) {
  const id = 'job-' + next++;
  jobs.set(id, { id, kind, params, status: 'queued' });
  setImmediate(() => {
    const job = jobs.get(id);
    job.status = 'running';
    job.result = run(params);
    job.status = 'done';
    job.finishedAt = Date.now();
  });
  return id;
}

function status(id) {
  return jobs.get(id) ?? null;
}

module.exports = { enqueue, status };
